    [9, 9, 9, 9, 9, 8, 9, 8, 9, 9, 9, 9]
])

# Find 4-connected components of 8s
def find_components(grid, target_val):
    h, w = grid.shape
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] == target_val and (r, c) not in visited:
                comp = []
                q = deque([(r, c)])
                while q:
                    cr, cc = q.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] == target_val:
                            q.append((nr, nc))
                components.append(comp)
    return components

